Helpers

as_label &lt;- function(x) {
  if (inherits(x, "haven_labelled")) {
    as_factor(x, levels = "labels")
  } else {
    x
  }
}

num_value &lt;- function(x) {
  suppressWarnings(as.numeric(zap_labels(x)))
}

text_value &lt;- function(x) {
  tolower(trimws(as.character(as_label(x))))
}

yes_no &lt;- function(x) {
  z &lt;- num_value(x)
  fifelse(
    is.na(z),
    NA_integer_,
    fifelse(z == 1, 1L, fifelse(z == 2, 0L, NA_integer_))
  )
}

selected_binary &lt;- function(x) {
  z &lt;- num_value(x)
  fifelse(is.na(z), NA_integer_, fifelse(z == 1, 1L, 0L))
}

current_use &lt;- function(x) {
  z &lt;- num_value(x)
  txt &lt;- text_value(x)

  fifelse(
    is.na(z) & is.na(txt),
    NA_integer_,
    fifelse(z == 1 | grepl("currently use", txt), 1L, 0L)
  )
}

agree_binary &lt;- function(x) {
  z &lt;- num_value(x)
  txt &lt;- text_value(x)

  fifelse(
    is.na(z) & is.na(txt),
    NA_integer_,
    fifelse(z == 1 | txt == "agree", 1L, fifelse(z == 2 | txt == "disagree", 0L, NA_integer_))
  )
}

worried_binary &lt;- function(x) {
  z &lt;- num_value(x)
  fifelse(
    is.na(z),
    NA_integer_,
    fifelse(z %in% c(1, 2), 1L, fifelse(z %in% c(3, 4), 0L, NA_integer_))
  )
}

difficulty_binary &lt;- function(x) {
  z &lt;- num_value(x)
  fifelse(
    is.na(z),
    NA_integer_,
    fifelse(z %in% c(1, 2), 1L, fifelse(z == 3, 0L, NA_integer_))
  )
}

count_value &lt;- function(x) {
  z &lt;- num_value(x)
  fifelse(is.na(z) | z &gt;= 98, NA_real_, z)
}

any_disability &lt;- function(...) {
  mat &lt;- cbind(...)
  vals &lt;- apply(mat, 1, function(row) {
    if (all(is.na(row))) {
      return(NA_integer_)
    }

    as.integer(any(row %in% c(2, 3, 4), na.rm = TRUE))
  })
  vals
}

score_band &lt;- function(x) {
  cut(
    x,
    breaks = c(-Inf, 0, 1, 3, Inf),
    labels = c("none", "low", "medium", "high"),
    right = TRUE
  )
}

weighted_mean &lt;- function(x, w) {
  ok &lt;- !is.na(x) & !is.na(w) & w &gt; 0
  if (!any(ok)) {
    return(NA_real_)
  }

  sum(x[ok] * w[ok]) / sum(w[ok])
}

weighted_total &lt;- function(x, w) {
  ok &lt;- !is.na(x) & !is.na(w) & w &gt; 0
  sum(x[ok] * w[ok])
}

Reading the results
The most important outputs are the leaf burden tables, not only the tree plot. A strong thesis-style finding has four parts:

a clear rule describing the subgroup;
high weighted food-vulnerability prevalence;
enough weighted population share to matter;
a high share of all food-vulnerable adults captured by that leaf.

The clean tree should be read as subgroup discovery. The mechanism tree should be read as diagnosis. The logistic model and tidymodels cross-validation check are there to keep the story honest.

Tree plot design helpers
These plot helpers mirror the thesis report style: compact split labels on edges, rounded split-variable boxes, and terminal boxes that report weighted subgroup burden.

tree_edge_panel_values_only &lt;- function(
  obj,
  var_labels = NULL,
  digits = 3,
  fill = "white",
  justmin = 4,
  just = c("alternate", "increasing", "decreasing", "equal"),
  max_items = 3L,
  max_chars = 24L,
  plural_label = "levels",
  ...
) {
  meta &lt;- obj$data

  compact_split_value &lt;- function(label) {
    label &lt;- gsub("\\s+", " ", trimws(label))
    if (!grepl(",", label, fixed = TRUE)) {
      return(paste(strwrap(label, width = max_chars), collapse = "\n"))
    }

    parts &lt;- trimws(strsplit(label, ",", fixed = TRUE)[[1L]])
    if (length(parts) &lt;= max_items && nchar(label) &lt;= max_chars) {
      return(paste(strwrap(label, width = max_chars), collapse = "\n"))
    }

    shown &lt;- paste(parts[seq_len(min(max_items, length(parts)))], collapse = ", ")
    paste0(
      length(parts), " ", plural_label, "\n",
      paste(strwrap(paste0(shown, ", ..."), width = max_chars), collapse = "\n")
    )
  }

  justfun &lt;- function(i, split_labels) {
    myjust &lt;- if (mean(nchar(split_labels)) &gt; justmin) {
      match.arg(just, c("alternate", "increasing", "decreasing", "equal"))
    } else {
      "equal"
    }

    k &lt;- length(split_labels)
    rval &lt;- switch(myjust,
      equal = rep.int(0, k),
      alternate = rep(c(0.5, -0.5), length.out = k),
      increasing = seq(from = -k / 2, to = k / 2, by = 1),
      decreasing = seq(from = k / 2, to = -k / 2, by = -1)
    )

    grid::unit(0.5, "npc") + grid::unit(rval[i], "lines")
  }

  function(node, i) {
    split_info &lt;- partykit::character_split(
      partykit::split_node(node),
      meta,
      digits = digits
    )
    split_labels &lt;- vapply(split_info$levels, compact_split_value, character(1L))

    y &lt;- justfun(i, split_labels)
    label &lt;- split_labels[[i]]
    label_lines &lt;- strsplit(label, "\n", fixed = TRUE)[[1L]]
    widest_line &lt;- label_lines[which.max(nchar(label_lines))]

    grid::grid.rect(
      y = y,
      gp = grid::gpar(fill = fill, col = NA),
      width = grid::unit(1.05, "strwidth", widest_line),
      height = grid::unit(max(1L, length(label_lines)), "lines")
    )
    grid::grid.text(label, y = y, just = "center")
  }
}
class(tree_edge_panel_values_only) &lt;- "grapcon_generator"

tree_inner_panel_compact_labeled &lt;- function(
  obj,
  var_labels = NULL,
  id = FALSE,
  show_p = FALSE,
  gp = grid::gpar(),
  fill = "white",
  max_chars = 34L,
  min_chars = 8L,
  ...
) {
  meta &lt;- obj$data

  pretty_var_name &lt;- function(var_name) {
    if (!is.null(var_labels) && var_name %in% names(var_labels)) {
      return(unname(var_labels[[var_name]]))
    }
    gsub("_", " ", var_name)
  }

  extract_label &lt;- function(node) {
    if (partykit::is.terminal(node)) {
      return(list(label = "", p = ""))
    }

    split_info &lt;- partykit::character_split(partykit::split_node(node), meta)
    varlab &lt;- pretty_var_name(split_info$name)

    plab &lt;- ""
    if (show_p) {
      pvalue &lt;- tryCatch({
        value &lt;- partykit::info_node(node)$p.value
        if (length(value) != 1L) NA_real_ else as.numeric(value)
      }, error = function(e) NA_real_)
      plab &lt;- if (is.na(pvalue)) {
        ""
      } else if (pvalue &lt; 0.001) {
        "p &lt; 0.001"
      } else {
        paste0("p = ", format(round(pvalue, 3), nsmall = 3))
      }
    }

    list(label = varlab, p = plab)
  }

  function(node) {
    lab &lt;- extract_label(node)
    label_lines &lt;- unlist(lapply(
      strsplit(lab$label, "\n", fixed = TRUE)[[1L]],
      strwrap,
      width = max_chars
    ))
    if (!length(label_lines)) {
      label_lines &lt;- ""
    }

    all_lines &lt;- c(label_lines, if (nzchar(lab$p)) lab$p)
    widest_line &lt;- all_lines[which.max(nchar(all_lines))]
    if (nchar(widest_line) &lt; min_chars) {
      widest_line &lt;- paste(rep("a", min_chars), collapse = "")
    }

    label_text &lt;- paste(label_lines, collapse = "\n")
    line_count &lt;- length(label_lines) + if (nzchar(lab$p)) 1L else 0L

    grid::pushViewport(grid::viewport(gp = gp))
    grid::pushViewport(
      grid::viewport(
        x = grid::unit(0.5, "npc"),
        y = grid::unit(0.5, "npc"),
        width = grid::unit(1.12, "strwidth", widest_line),
        height = grid::unit(line_count + 0.8, "lines")
      )
    )

    grid::grid.roundrect(
      r = grid::unit(0.12, "snpc"),
      gp = grid::gpar(fill = fill, col = "#cfd8dc", lwd = 0.8)
    )
    grid::grid.text(
      label_text,
      y = grid::unit(if (nzchar(lab$p)) 0.62 else 0.5, "npc")
    )
    if (nzchar(lab$p)) {
      grid::grid.text(
        lab$p,
        y = grid::unit(0.22, "npc"),
        gp = grid::gpar(cex = 0.85)
      )
    }

    grid::upViewport(2)
  }
}
class(tree_inner_panel_compact_labeled) &lt;- "grapcon_generator"

tree_terminal_panel_food &lt;- function(
  obj,
  leaf_stats,
  fill = "#d9d9d9",
  gp = grid::gpar(fontsize = 9),
  width_lines = 7,
  height_lines = 4.8,
  ...
) {
  stats &lt;- as.data.table(leaf_stats)

  function(node) {
    node_id &lt;- partykit::id_node(node)
    row &lt;- stats[node == node_id]

    if (!nrow(row)) {
      label &lt;- paste0("Node ", node_id)
    } else {
      label &lt;- paste(
        paste0("Node ", node_id),
        paste0("n: ", format(round(row$weighted_population), big.mark = ",", scientific = FALSE)),
        paste0("Food poor: ", sprintf("%.1f%%", row$prevalence_pct)),
        paste0("Pop share: ", sprintf("%.1f%%", row$population_share_pct)),
        paste0("Lift: ", sprintf("%.2fx", row$lift)),
        sep = "\n"
      )
    }

    grid::pushViewport(grid::viewport(gp = gp))
    grid::pushViewport(
      grid::viewport(
        width = grid::unit(width_lines, "lines"),
        height = grid::unit(height_lines, "lines")
      )
    )
    grid::grid.roundrect(
      r = grid::unit(0.08, "snpc"),
      gp = grid::gpar(fill = fill, col = "#b0bec5", lwd = 0.8)
    )
    grid::grid.text(label, x = grid::unit(0.08, "npc"), just = "left")
    grid::upViewport(2)
  }
}
class(tree_terminal_panel_food) &lt;- "grapcon_generator"

