plot_finaccess_tree &lt;- function(tree_party, leaf_stats, var_labels = finaccess_var_labels) {
  plot(
    tree_party,
    gp = grid::gpar(fontsize = 9, col = "#18212f"),
    terminal_panel = tree_terminal_panel_food,
    tp_args = list(leaf_stats = leaf_stats),
    inner_panel = tree_inner_panel_compact_labeled,
    ip_args = list(var_labels = var_labels, fill = "#ffffff", show_p = FALSE),
    edge_panel = tree_edge_panel_values_only,
    ep_args = list(max_chars = 24L),
    tnex = 1.05
  )
}
